  'fronts/la-descente-de-la-griffe.json':
    '{"id":"la-descente-de-la-griffe","name":"La descente de la Griffe","periodId":"freljord-moderne","portents":["Une bande de guerre hiverne plus bas que d\'habitude, et ne remonte pas au dégel.","Le tribut demandé au premier hameau double, et le hameau paie sans discuter.","Le Col Battu change de main une nuit, sans un mort, et la route du grain avec lui.","Les convois ne partent plus sans escorte, et l\'escorte coûte plus cher que ce qu\'elle garde.","Un hameau du versant bas ouvre ses portes de lui-même, pour cesser d\'attendre.","La Griffe d\'Hiver n\'a plus besoin de descendre : on lui monte tout."],"regionIds":["ice-reaches","freljord","avarosa-reach"],"schemaVersion":1,"segments":6,"stake":"Les hameaux du versant bas, et le droit d\'y passer l\'hiver sans payer de tribut à qui que ce soit.","tags":["territoire-conteste","tribut","bande-de-guerre"]}',
  'fronts/la-fracture-des-trois.json':
    '{"id":"la-fracture-des-trois","name":"La fracture des trois","periodId":"guerre-des-trois-soeurs","portents":["L\'une des trois cesse de venir aux conseils, et envoie quelqu\'un à sa place.","Un secret vieux d\'une génération se dit à voix haute devant un témoin de trop.","Les clans choisissent leur sœur, et les familles se coupent en deux.","La Vraie Glace est prise à celle qui la portait, et nul ne dit par quelle main.","Une armée passe le col en plein hiver, ce qu\'aucune n\'avait osé jusque-là.","Le rituel est prononcé au bord de la faille, et la faille répond.","Deux des trois disparaissent le même jour, et les récits ne s\'accordent pas.","Il ne reste qu\'un nord fendu, trois héritages, et aucune paix à se partager."],"regionIds":["howling-abyss","freljord"],"schemaVersion":1,"segments":8,"stake":"L\'union que trois sœurs ont mis une vie à bâtir, et les clans qui avaient fini par y croire.","tags":["rupture","vraie-glace"]}',
  'fronts/la-veille-qui-s-impatiente.json':
    '{"id":"la-veille-qui-s-impatiente","name":"La veille qui s\'impatiente","periodId":"freljord-moderne","portents":["Des voyageurs sont accueillis à la Citadelle et repartent avec moins de questions qu\'à l\'arrivée.","On demande aux clans du haut de céder leurs vieilles pierres gravées, contre du sel.","Un couloir de la Citadelle descend plus bas qu\'au dernier passage, et personne ne l\'a creusé.","Les bêtes désertent la Faille Hurlante, toutes le même jour.","Un veilleur quitte son poste sans explication, et sa place est comblée avant le soir.","Le gel remonte les vallées à contre-saison, en suivant les anciennes routes.","Un chant sans paroles s\'entend la nuit au fond du col, et les enfants le répètent au matin.","La Citadelle ferme ses portes aux marchands, pour la première fois de mémoire d\'homme.","La glace de la Faille se fend d\'un bord à l\'autre, sans bruit.","Ce qu\'on gardait n\'est plus gardé, et le nord apprend enfin ce qu\'on lui cachait."],"regionIds":["frostguard-citadel","howling-abyss","freljord"],"schemaVersion":1,"segments":10,"stake":"Ce qui dort sous la Faille, et le silence qu\'on entretient autour depuis assez longtemps pour qu\'il passe pour du calme.","tags":["territoire-conteste","veille","sous-la-glace"]}',
  'fronts/le-froid-qui-descend-du-col.json':
    '{"id":"le-froid-qui-descend-du-col","name":"Le froid qui descend du col","periodId":"freljord-moderne","portents":["La neige tombe une semaine trop tôt, et ne fond plus entre deux chutes.","Le pont de planches prend le gel, et le bois travaille dessous.","Le hameau brûle ses réserves de bois avant la mi-hiver.","Le toit de la salle commune cède une nuit, sur ceux qui s\'y étaient serrés."],"regionIds":["rakelstake","freljord"],"schemaVersion":1,"segments":4,"stake":"Les toits du hameau des pics, et les quarante feux qui dorment dessous.","tags":["hiver","hameau"]}',
  'fronts/le-serment-du-grenier.json':
    '{"id":"le-serment-du-grenier","name":"Le serment du grenier","periodId":"freljord-moderne","portents":["Deux clans signent pour le grain d\'hiver et repartent avec plus qu\'ils n\'ont apporté.","Le compte du grenier cesse d\'être relu à voix haute devant témoin.","Un hameau qui a refusé de signer est servi en dernier, et l\'apprend par un voisin.","Une escorte en armes accompagne le convoi, et personne n\'appelle ça une garnison.","Le gué bas est fermé à qui n\'a pas prêté serment, sous prétexte de gel.","Un clan rend son tribut deux fois dans la saison pour garder sa place à la table.","Le conseil vote une mesure sans les absents, puis déclare les absents sortis.","La Marche nourrit le nord et le tient : plus personne ne peut partir sans avoir faim."],"regionIds":["avarosa-reach","rakelstake","freljord"],"schemaVersion":1,"segments":8,"stake":"Le grain mis en commun, et l\'idée qu\'on puisse réunir le nord sans écraser personne pour y arriver.","tags":["territoire-conteste","grain","serment"]}',
  'fronts/les-murs-de-glace-se-fendent.json':
    '{"id":"les-murs-de-glace-se-fendent","name":"Les murs de glace se fendent","periodId":"la-longue-nuit","portents":["Une fissure apparaît là où la glace avait été fondue puis reprise.","Les veilleurs cessent de se relayer par deux, faute de bras valides.","L\'un d\'eux redescend seul, remonte au matin, et dit n\'avoir rien vu.","Les yétis abandonnent les hauteurs et deviennent dangereux dans les vallées.","Le mur tient encore, mais on entend distinctement au travers.","Ceux qui gardent décident qu\'il vaut mieux parler à ce qu\'ils gardent."],"regionIds":["frostguard-citadel","howling-abyss"],"schemaVersion":1,"segments":6,"stake":"Le mur dressé sur ce qui regardait, et les vies qu\'il a coûtées pour être dressé.","tags":["mur","veille"]}',
  'hooks/ce-qu-on-ne-mendie-plus.json':
    '{"appliesTo":{"championId":"sejuani","kind":"champion"},"id":"ce-qu-on-ne-mendie-plus","name":"Ce qu\'on ne mendie plus","periodId":"freljord-moderne","pitch":"Une bande a hiverné en bas sans qu\'on le lui accorde et n\'est pas remontée au dégel. Elle porte encore les mêmes couleurs, elle prend en leur nom, et elle n\'obéit plus à personne.","schemaVersion":1,"suggestedBondIds":["ulfar-le-preneur","torvald-qui-est-descendu"],"tags":["commandement","bande-de-guerre"],"vowRank":"redoutable"}',
