  'hooks/la-porte-qu-on-vous-doit.json':
    '{"appliesTo":{"championId":"braum","kind":"champion"},"id":"la-porte-qu-on-vous-doit","name":"La porte qu\'on vous doit","periodId":"freljord-moderne","pitch":"Le hameau des pics a tenu l\'hiver dernier parce que quelqu\'un s\'est mis devant. Cette année le convoi n\'est pas arrivé, le pont ne portera pas un homme de plus, et on attend la même personne.","schemaVersion":1,"suggestedBondIds":["l-enfant-du-pont","katla-la-compteuse"],"tags":["protection","hameau"],"vowRank":"dangereux"}',
