  'hooks/un-seul-nord-a-nourrir.json':
    '{"appliesTo":{"championId":"ashe","kind":"champion"},"id":"un-seul-nord-a-nourrir","name":"Un seul nord à nourrir","periodId":"freljord-moderne","pitch":"Le compte du grenier n\'est plus relu devant témoin, et deux clans s\'en servent déjà comme d\'une preuve. Ce qui se défait au conseil n\'est pas du grain, c\'est la seule chose qui tenait les clans ensemble.","schemaVersion":1,"suggestedBondIds":["katla-la-compteuse","brynja-la-tardive"],"tags":["commandement","grain"],"vowRank":"extreme"}',
